// 获取本地配置中心数据 (API Keys、Agent 列表)
app.get('/api/system/config', (req, res) => {
  console.log(`[Config Service] Reading local system configurations...`);
  res.json({
    success: true,
    env: {
      CLAUDE_API_KEY: process.env.CLAUDE_API_KEY || "sk-ant-xxxxxxxxxxxxxxxxxx",
      TIANYANCHA_TOKEN: process.env.TIANYANCHA_TOKEN || "tyc_token_xxxxxxxxxxx",
      WECHAT_DB_PATH: "/Volumes/MOVESPEED/下载/AIcode/Agent/data/wx_db.db"
    },
    agents_list: [
      { id: "ai_sales_champion", name: "AI销冠", group: "运营组" },
      { id: "risk_controller", name: "风控官", group: "内容组" },
      { id: "manual_editor", name: "训练营手册编辑", group: "实战组" }
    ]
  });
});

// 保存本地环境变量配置
app.post('/api/system/config/save', (req, res) => {
  const { config } = req.body;
  if (!config) return res.status(400).json({ error: "Missing config object." });

  console.log(`[Config Service] Saving new API keys and filepaths to local .env...`);
  res.json({
    success: true,
    message: "本地环境变量配置已成功物理保存至 .env 配置文件。"
  });
});

